import {
  CopyObjectCommand,
  DeleteObjectCommand,
  GetObjectCommand,
  PutObjectCommand,
  S3Client
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

function storageConfig() {
  // Accept both the application's provider-neutral names and the standard
  // AWS-compatible names generated by Neon Object Storage.
  const endpoint = process.env.S3_ENDPOINT ?? process.env.AWS_ENDPOINT_URL_S3;
  const accessKeyId = process.env.S3_ACCESS_KEY_ID ?? process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.S3_SECRET_ACCESS_KEY ?? process.env.AWS_SECRET_ACCESS_KEY;
  const publicBucket = process.env.S3_BUCKET_PUBLIC;
  const privateBucket = process.env.S3_BUCKET_PRIVATE;
  if (!endpoint || !accessKeyId || !secretAccessKey || !publicBucket || !privateBucket) return null;

  const forcePathStyle = process.env.S3_FORCE_PATH_STYLE === "true";
  const publicBaseUrl =
    process.env.S3_PUBLIC_BASE_URL ??
    (forcePathStyle ? `${endpoint.replace(/\/$/, "")}/${publicBucket}` : undefined);

  return {
    endpoint,
    accessKeyId,
    secretAccessKey,
    publicBucket,
    privateBucket,
    publicBaseUrl,
    region: process.env.S3_REGION ?? process.env.AWS_REGION ?? "auto",
    forcePathStyle
  };
}

export function isStorageConfigured() {
  return Boolean(storageConfig());
}

function client() {
  const config = storageConfig();
  if (!config) throw new Error("Object storage belum dikonfigurasi.");
  return {
    config,
    s3: new S3Client({
      endpoint: config.endpoint,
      region: config.region,
      forcePathStyle: config.forcePathStyle,
      credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
    })
  };
}

export async function putObject(input: {
  objectKey: string;
  body: Buffer;
  contentType: string;
  visibility: "PUBLIC" | "PRIVATE";
}) {
  const { config, s3 } = client();
  const bucket = input.visibility === "PUBLIC" ? config.publicBucket : config.privateBucket;
  await s3.send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: input.objectKey,
      Body: input.body,
      ContentType: input.contentType,
      CacheControl:
        input.visibility === "PUBLIC" ? "public, max-age=31536000, immutable" : "private, no-store"
    })
  );
  return input.visibility === "PUBLIC" && config.publicBaseUrl
    ? `${config.publicBaseUrl.replace(/\/$/, "")}/${input.objectKey}`
    : null;
}

export async function deleteObject(objectKey: string, visibility: "PUBLIC" | "PRIVATE") {
  const { config, s3 } = client();
  await s3.send(
    new DeleteObjectCommand({
      Bucket: visibility === "PUBLIC" ? config.publicBucket : config.privateBucket,
      Key: objectKey
    })
  );
}

export async function copyPrivateObjectToPublic(objectKey: string, contentType: string) {
  const { config, s3 } = client();
  if (!config.publicBaseUrl) throw new Error("Alamat bucket publik belum dikonfigurasi.");
  await s3.send(
    new CopyObjectCommand({
      Bucket: config.publicBucket,
      Key: objectKey,
      CopySource: `${config.privateBucket}/${objectKey.split("/").map(encodeURIComponent).join("/")}`,
      ContentType: contentType,
      MetadataDirective: "REPLACE",
      CacheControl: "public, max-age=31536000, immutable"
    })
  );
  return `${config.publicBaseUrl.replace(/\/$/, "")}/${objectKey}`;
}

export async function createPrivateDownloadUrl(objectKey: string, expiresIn = 300) {
  const { config, s3 } = client();
  return getSignedUrl(s3, new GetObjectCommand({ Bucket: config.privateBucket, Key: objectKey }), {
    expiresIn
  });
}
